"""
GB gas power, 2025 fleet — ecoinvent's GB combined-cycle plant at DESNZ DUKES 2025 fleet efficiency.
=============================================================================

Source and scope
----------------
**Functional unit: 1 kWh of electricity generated by Britain's gas fleet in
2025, at high voltage.** It scores the ``GAS`` share of every grid series
(``optimiser_lca.grid.SOURCES``).

ecoinvent 3.9.1's 'electricity production, natural gas, combined cycle power
plant' [GB] is one new 400 MW plant (its comment: 260 MW gas turbine and 140 MW
steam turbine, UK, 2012). Its 0.3231 kg of fossil CO2 per kWh puts it at about
57 % efficiency on a gross calorific basis. Britain's combined-cycle fleet ran
at 47.99 % gross in 2025 (DESNZ, DUKES 2026, table 5.10.C, major power
producers, 30 July 2026). That fleet also runs at part load and starts and
stops to follow wind, which a single plant at its design point does not. So the
ecoinvent plant burns about 16 % too little gas per kWh.

The fleet's kWh is therefore ecoinvent's kWh scaled by one fuel factor: the
fleet's CO2 at the plant over the dataset's own. The fleet's is DESNZ's CO2 per
kWh of gas burned (GHG conversion factors 2026, "Fuels" sheet, natural gas,
100 % mineral blend, kWh gross) divided by the DUKES efficiency. Everything in
the dataset that follows the fuel scales with it: the gas and its supply chain
(ecoinvent's GB high-pressure market), combustion emissions, and cooling water.

Checked against the published figures it replaces (23 Nov 2026):
- NESO's Carbon Intensity API scores gas CCGT at 394 g CO2/kWh, direct only,
  per kWh supplied (Carbon Intensity Forecast Methodology, January 2021,
  Table 1). This module's CO2 at the plant is 383.5 g per kWh generated, which
  is the same within the plant's own use.
- The supply chain, 72.8 g/kWh, sits beside DESNZ's well-to-tank factor for
  natural gas over the same efficiency (63.0 g/kWh).
- The total is 459.7 g CO2e/kWh, against the dataset's 387.3.
"""
from __future__ import annotations

from optimiser_lca import registry as R
from optimiser_lca.common import Activity, Inventory, Process

# =============================================================================
# Parameters
# =============================================================================
# TRANSCRIBED - DESNZ, DUKES 2026, table 5.10.C, combined cycle gas turbine
# stations, 2025, thermal efficiency, gross calorific value basis, major power producers.
GAS_FLEET_EFFICIENCY_GROSS = 0.4799
# TRANSCRIBED - DESNZ GHG conversion factors 2026 (11 Jun 2026), "Fuels", natural gas
# (100% mineral blend), kWh (Gross CV), kg CO2 per kWh of gas. Power stations burn
# transmission gas, which carries none of the biomethane blended into distribution.
GAS_CO2_KG_PER_KWH_GROSS = 0.18405
# TRANSCRIBED - ecoinvent 3.9.1 apos, 'electricity production, natural gas, combined
# cycle power plant' [GB], 'Carbon dioxide, fossil' to air, kg per kWh.
GAS_ECOINVENT_CO2_KG_PER_KWH = 0.32309243697479

# DERIVED - the fleet's CO2 at the plant per kWh generated, and the factor that scales
# the dataset's fuel-driven exchanges to it.
GAS_FLEET_CO2_KG_PER_KWH = GAS_CO2_KG_PER_KWH_GROSS / GAS_FLEET_EFFICIENCY_GROSS
GAS_FLEET_FUEL_FACTOR = GAS_FLEET_CO2_KG_PER_KWH / GAS_ECOINVENT_CO2_KG_PER_KWH
# DERIVED - the dataset's own efficiency on the same basis, for the record.
GAS_ECOINVENT_EFFICIENCY_GROSS = GAS_CO2_KG_PER_KWH_GROSS / GAS_ECOINVENT_CO2_KG_PER_KWH

GAS_FLEET_SCOPE = {
    "fuel_and_combustion": "INCLUDED - the dataset's gas, its GB high-pressure supply chain, the stack "
                           "emissions and cooling water, all x GAS_FLEET_FUEL_FACTOR.",
    "plant_construction": "INCLUDED - scaled with the fuel as well, so 0.2 g/kWh high (1.0 g/kWh unscaled); "
                          "kept whole rather than split out of the dataset.",
    "open_cycle_gas": "SUBSTITUTED - the API's gas share includes a little open-cycle generation, scored "
                      "here at the combined-cycle fleet's efficiency: errs low.",
    "basis": "SUBSTITUTED - DUKES efficiency is per kWh generated; ecoinvent's reference flow is at the "
             "busbar. Station own use (about 2 %) is not added: errs low.",
}


def check() -> str:
    """The factor and both efficiencies, against the bounds a real fleet allows."""
    if not 0.40 < GAS_FLEET_EFFICIENCY_GROSS < GAS_ECOINVENT_EFFICIENCY_GROSS < 0.62:
        raise AssertionError(f"efficiencies out of order: fleet {GAS_FLEET_EFFICIENCY_GROSS:.3f}, "
                             f"ecoinvent plant {GAS_ECOINVENT_EFFICIENCY_GROSS:.3f}")
    if not 1.0 < GAS_FLEET_FUEL_FACTOR < 1.4:
        raise AssertionError(f"fuel factor {GAS_FLEET_FUEL_FACTOR:.4f} is outside 1.0-1.4")
    return describe()


# =============================================================================
# Processes — exact identities, with the search that found each one
# =============================================================================
processes = {
    "ccgt_gb": Process(
        identity=("electricity production, natural gas, combined cycle power plant", "GB",
                  "electricity, high voltage"),
        query="electricity production natural gas combined cycle GB",
        why="the GB combined-cycle dataset; the conventional plant (558 g/kWh) is not GB's fleet"),
}
flows = {}

# =============================================================================
# Activities
# =============================================================================
FLEET = Activity(
    code=R.GAS_FLEET_CCGT_2025,
    name="electricity production, natural gas, GB combined-cycle fleet 2025",
    reference_product="electricity, high voltage", unit="kilowatt hour", location="GB",
    comment="ecoinvent 3.9.1 'electricity production, natural gas, combined cycle power plant' [GB], its "
            "fuel-driven exchanges scaled to DESNZ DUKES 2026 table 5.10.C's 2025 fleet efficiency "
            "(47.99 % gross), with DESNZ 2026's CO2 per kWh of natural gas.",
    technosphere=[
        ("ccgt_gb", GAS_FLEET_FUEL_FACTOR, "kilowatt hour",
         "DERIVED - (0.18405 / 0.4799) / 0.32309: the fleet's CO2 per kWh over the dataset's"),
    ],
)

activities = [FLEET]


def inventory() -> Inventory:
    return Inventory(name="GB gas fleet 2025 (ecoinvent CCGT at DUKES efficiency)", database=R.GAS_FLEET_DB,
                     processes=processes, flows=flows, activities=activities)


def describe() -> str:
    return (f"GB gas fleet 2025: {GAS_FLEET_EFFICIENCY_GROSS:.2%} gross (DUKES) against the ecoinvent plant's "
            f"{GAS_ECOINVENT_EFFICIENCY_GROSS:.2%}; CO2 at the plant {GAS_FLEET_CO2_KG_PER_KWH * 1000:.1f} g/kWh; "
            f"fuel factor {GAS_FLEET_FUEL_FACTOR:.4f}")
